-- gap-12 — Mental Health: substance use, abuse dynamics and psychiatric crisis
-- Batch: gapfill-20260728   Items: 35   ID block: 551001-551035
-- Subject: Mental Health. Body systems: Psychiatric/Mental Health, Multisystem.

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MAT_551001', 'MATRIX', 'The nurse is planning care for six clients on an acute admission unit. For each client, select whether the nurse should anticipate central nervous system overactivity or central nervous system depression.', 'Two of the four substance quadrants drive the body up and two drive it down. Overdose of a stimulant and withdrawal from a depressant both produce overactivity — agitation, tachycardia, hypertension, hyperreflexia and seizure risk. Overdose of a depressant and withdrawal from a stimulant both produce depression — sedation, bradycardia and, in overdose, respiratory arrest. Working out the quadrant tells the nurse which emergency to prepare for before any symptom appears.', '{"rows":[{"id":"r1","text":"A client who has taken an overdose of amphetamine"},{"id":"r2","text":"A client whose last alcoholic drink was 30 hours ago and who is now tremulous"},{"id":"r3","text":"A client who has taken an overdose of oral morphine"},{"id":"r4","text":"A client who stopped heavy cocaine use 2 days ago"},{"id":"r5","text":"A client who has taken an overdose of diazepam"},{"id":"r6","text":"A client who abruptly stopped a nightly barbiturate hypnotic 2 days ago"}],"columns":[{"id":"c1","text":"Central nervous system overactivity"},{"id":"c2","text":"Central nervous system depression"}],"row_label":"Client"}'::jsonb, '{"cells":{"r1":"c1","r2":"c1","r3":"c2","r4":"c2","r5":"c2","r6":"c1"},"feedback":{}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Mental Health', 'Multisystem',
 'Substance intoxication and withdrawal', 'Stimulant and depressant quadrants', 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_551002', 'MCQ', 'A client has taken lorazepam every night for 3 years and stopped it abruptly 2 days ago. The client is now tremulous and diaphoretic, with a heart rate of 118 beats per minute and a blood pressure of 162/98 mmHg. Which nursing precaution is the PRIORITY?', 'A benzodiazepine is a central nervous system depressant. When it is removed abruptly, the nervous system rebounds upward and the client is at risk of a withdrawal seizure — the same risk carried by alcohol withdrawal. Respiratory depression belongs to the other side of the grid, depressant overdose, and is not what this client is heading towards.', '{"options":[{"id":"A","text":"Institute seizure precautions and keep suction available at the bedside"},{"id":"B","text":"Place a bag-valve-mask at the bedside and prepare to support ventilation"},{"id":"C","text":"Restrict oral fluids until the blood pressure returns to baseline"},{"id":"D","text":"Encourage the client to sleep in a darkened room without interruption"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Withdrawal from a depressant produces central nervous system overactivity, and a seizure is the emergency to prepare for.","B":"Incorrect. Respiratory depression is a feature of depressant overdose, not depressant withdrawal.","C":"Incorrect. Fluid restriction does not treat withdrawal, and the client is more likely to need fluids because of diaphoresis.","D":"Incorrect. Long uninterrupted periods without observation are unsafe when a client may seize."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Mental Health', 'Psychiatric/Mental Health',
 'Benzodiazepine withdrawal', 'Seizure precautions', 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_551003', 'MCQ', 'Four clients arrive in the emergency department at the same time. Which client is at greatest risk of respiratory arrest?', 'Respiratory arrest is the danger of the depressant overdose quadrant, and the risk multiplies when two depressants are combined, because both suppress the brainstem drive to breathe. The other three clients sit in quadrants that carry different dangers — seizure and hyperthermia in stimulant intoxication and alcohol withdrawal, and a distressing but not life-threatening crash in stimulant withdrawal.', '{"options":[{"id":"A","text":"A 22-year-old who took oxycodone and diazepam together 40 minutes ago"},{"id":"B","text":"A 35-year-old whose last drink was 30 hours ago, who is tremulous with a heart rate of 112 beats per minute"},{"id":"C","text":"A 19-year-old who used cocaine 1 hour ago and is agitated with a temperature of 38.9 degrees C"},{"id":"D","text":"A 40-year-old who stopped methamphetamine 3 days ago and has been sleeping for most of the day"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Two central nervous system depressants taken together produce additive respiratory depression and the highest risk of arrest.","B":"Incorrect. Alcohol withdrawal drives the body up, so this client is at risk of seizure rather than respiratory arrest.","C":"Incorrect. Stimulant intoxication carries seizure, arrhythmia and hyperthermia risk, not respiratory depression.","D":"Incorrect. Stimulant withdrawal produces hypersomnia and low mood, which is uncomfortable but does not stop respiration."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care', 'Mental Health', 'Multisystem',
 'Overdose triage', 'Respiratory arrest risk', 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SATA_551004', 'SATA', 'A client is admitted 48 hours after stopping heavy daily cocaine use. Which findings should the nurse expect? Select all that apply.', 'Withdrawal from a stimulant is the mirror image of taking it, so the client crashes downward — sleeping heavily, eating more, moving and thinking slowly, and feeling flat with intense craving. The frightening features candidates often attach to cocaine, such as hyperthermia, severe hypertension and seizures, belong to intoxication, not to withdrawal. Stimulant withdrawal is rarely dangerous physically, but the depressed mood carries a genuine suicide risk that must be assessed.', '{"options":[{"id":"A","text":"Excessive sleeping"},{"id":"B","text":"Increased appetite"},{"id":"C","text":"Depressed mood with intense craving for the drug"},{"id":"D","text":"Dilated pupils with a temperature of 39 degrees C"},{"id":"E","text":"Psychomotor slowing"},{"id":"F","text":"Generalised tonic-clonic seizures"},{"id":"G","text":"Blood pressure of 190/112 mmHg"}]}'::jsonb, '{"answers":["A","B","C","E"],"feedback":{"A":"Correct. Hypersomnia is a hallmark of the stimulant crash.","B":"Correct. Appetite returns and often increases once the appetite-suppressing drug is stopped.","C":"Correct. Dysphoria with strong craving is expected and is where the suicide risk lies.","D":"Incorrect. Pupil dilation with hyperthermia indicates stimulant intoxication, not withdrawal.","E":"Correct. Movement and thought slow down as the stimulant effect reverses.","F":"Incorrect. Seizures occur with stimulant intoxication and with depressant withdrawal, not with stimulant withdrawal.","G":"Incorrect. Severe hypertension is an intoxication finding; blood pressure tends to be normal or low in the crash."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Stimulant withdrawal', 'Expected findings', 'Easy', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_551005', 'MCQ', 'A client admitted for elective hernia repair reports that the last alcoholic drink was 26 hours ago. The client is alert and fully oriented, tremulous and nauseated, with a heart rate of 104 beats per minute and a blood pressure of 148/90 mmHg. How should the nurse interpret these findings?', 'Uncomplicated alcohol withdrawal begins around 24 hours after the last drink and produces tremor, nausea, sweating and mild autonomic arousal in a client who remains oriented. It is uncomfortable but not in itself life-threatening. Delirium tremens is a different condition that appears around 72 hours and is defined by disorientation, hallucinations and marked autonomic instability. Withdrawal always comes before delirium tremens, but most clients never progress to it.', '{"options":[{"id":"A","text":"Expected uncomplicated alcohol withdrawal, which is not in itself life-threatening"},{"id":"B","text":"Early delirium tremens, requiring immediate transfer to intensive care"},{"id":"C","text":"An expected reaction to the preoperative fasting regimen"},{"id":"D","text":"Evidence that the client is intoxicated at this moment"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. The timing and the preserved orientation fit uncomplicated withdrawal, which is monitored and treated on the ward.","B":"Incorrect. Delirium tremens appears around 72 hours and includes disorientation and hallucinations, which this client does not have.","C":"Incorrect. Fasting does not cause tremor with tachycardia and hypertension in a client who has recently stopped drinking.","D":"Incorrect. Intoxication would depress the nervous system; these findings show the nervous system rebounding upward."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Alcohol withdrawal', 'Timing and interpretation', 'Easy', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SELN_551006', 'SELECT_N', 'A client is in the third day of an admission for alcohol withdrawal. Which 3 findings indicate that the client is progressing to delirium tremens rather than continuing in uncomplicated withdrawal?', 'The line between the two conditions is drawn by sensorium and autonomic instability. Disorientation, hallucinations and a high fever with marked tachycardia mark delirium tremens, which carries a real mortality and needs urgent treatment. Tremor, nausea and disturbed sleep persist through ordinary withdrawal and do not by themselves signal progression.', '{"options":[{"id":"A","text":"Disorientation to time and place"},{"id":"B","text":"Visual hallucinations of insects on the bedding"},{"id":"C","text":"Temperature 38.7 degrees C with a heart rate of 132 beats per minute"},{"id":"D","text":"Mild bilateral hand tremor"},{"id":"E","text":"Nausea and loss of appetite"},{"id":"F","text":"Difficulty falling asleep"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Correct. A clouded sensorium separates delirium tremens from uncomplicated withdrawal.","B":"Correct. Vivid visual hallucinations, often of small crawling things, are characteristic of delirium tremens.","C":"Correct. Fever with severe tachycardia signals the autonomic storm of delirium tremens.","D":"Incorrect. Tremor is present in ordinary withdrawal from the first day.","E":"Incorrect. Nausea and anorexia are common throughout uncomplicated withdrawal.","F":"Incorrect. Insomnia is expected in withdrawal and does not indicate progression on its own."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Mental Health', 'Multisystem',
 'Delirium tremens', 'Recognising progression', 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SATA_551007', 'SATA', 'A client has been diagnosed with delirium tremens. Which interventions should the nurse include in the plan of care? Select all that apply.', 'Care for delirium tremens differs sharply from care for ordinary withdrawal. The client is disoriented, misperceives the environment and may act on hallucinations, so the plan centres on visibility, a low-stimulus but well-lit room, seizure precautions and restricted independent mobility until the delirium clears. Darkness and long unobserved periods increase misperception and the chance of an unwitnessed fall or seizure.', '{"options":[{"id":"A","text":"Place the client in a room close to the nurses station for frequent observation"},{"id":"B","text":"Keep the room quiet and well lit to reduce misperception of shadows"},{"id":"C","text":"Institute seizure precautions"},{"id":"D","text":"Assist the client with all movement out of bed"},{"id":"E","text":"Encourage the client to walk unaccompanied in the corridor to use up restless energy"},{"id":"F","text":"Turn off the lights and leave the client undisturbed for long periods to promote rest"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Proximity to staff allows the close, frequent observation this life-threatening state requires.","B":"Correct. A quiet, well-lit room reduces the shadows and noises that feed hallucinations.","C":"Correct. Seizure risk remains throughout the withdrawal period and is highest in delirium tremens.","D":"Correct. Mobility is restricted and supervised because the client is disoriented and at high risk of falling.","E":"Incorrect. Unaccompanied walking by a disoriented client invites injury and wandering.","F":"Incorrect. Darkness worsens misperception, and long unobserved periods are unsafe."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Mental Health', 'Psychiatric/Mental Health',
 'Delirium tremens', 'Environment and safety', 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_551008', 'MCQ', 'On the third day after admission, a client with a history of heavy daily alcohol use becomes disoriented, reports seeing insects crawling on the wall, and has a temperature of 38.6 degrees C, a heart rate of 134 beats per minute and a blood pressure of 176/104 mmHg. Which action should the nurse take FIRST?', 'Delirium tremens is a medical emergency with a measurable mortality, and it is treated pharmacologically — usually with a benzodiazepine — alongside fluids and electrolyte correction. Environmental measures and reorientation are part of the plan but they do not treat the autonomic storm, so the first action is to get the prescriber involved. Restraint is a last resort that can raise agitation, hyperthermia and injury risk.', '{"options":[{"id":"A","text":"Notify the healthcare provider, because this presentation is a medical emergency"},{"id":"B","text":"Reorient the client repeatedly to the day, the time and the place"},{"id":"C","text":"Apply wrist restraints to stop the client pulling at the intravenous line"},{"id":"D","text":"Dim the lights and close the door so that the client can rest"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Delirium tremens needs urgent medical treatment, so the provider must be informed without delay.","B":"Incorrect. Reorientation is supportive but does nothing for the fever, tachycardia and hypertension.","C":"Incorrect. Restraint is a last resort and can worsen agitation, hyperthermia and injury in delirium.","D":"Incorrect. Dim light increases misperception and hallucination in a delirious client."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care', 'Mental Health', 'Psychiatric/Mental Health',
 'Delirium tremens', 'First action', 'Very hard', 'CURATOR_LABEL', 'Evaluate', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_551009', 'MCQ', 'A client with a 20-year history of heavy alcohol use is admitted with confusion, an unsteady gait and abnormal eye movements. The client is hypoglycaemic. Which prescription should the nurse expect to give before any intravenous glucose is administered?', 'Wernicke encephalopathy is caused by thiamine deficiency, common in heavy alcohol use because thiamine intake and absorption both fall. Giving glucose first consumes the last of the thiamine store and can precipitate or deepen the encephalopathy. Prompt thiamine can prevent Wernicke encephalopathy and arrest it once it starts, but if it progresses to Korsakoff syndrome the memory loss is largely permanent.', '{"options":[{"id":"A","text":"Thiamine"},{"id":"B","text":"Cyanocobalamin (vitamin B12)"},{"id":"C","text":"Naloxone"},{"id":"D","text":"Phytomenadione (vitamin K)"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Thiamine precedes glucose, because glucose given first can precipitate or worsen Wernicke encephalopathy.","B":"Incorrect. Vitamin B12 deficiency causes a different neuropathy and is not the cause of this triad.","C":"Incorrect. Naloxone reverses opioids and has no role in thiamine deficiency.","D":"Incorrect. Vitamin K corrects clotting, which is a separate problem in liver disease."}}'::jsonb,
 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Mental Health', 'Multisystem',
 'Wernicke encephalopathy', 'Thiamine replacement', 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_551010', 'MCQ', 'A client with Korsakoff syndrome gives the nurse a detailed account of having spent the morning at a football match, although the client has been on the unit since breakfast. Which response by the nurse is BEST?', 'Confabulation is the filling of a memory gap with invented material that the client believes; it is not lying and it is not a delusion. Arguing cannot restore the memory and simply raises anxiety and defensiveness, while asking for more detail rewards and extends the story. A calm, matter-of-fact acknowledgement followed by redirection to something happening now preserves dignity and keeps the client oriented to the present.', '{"options":[{"id":"A","text":"You could not have been at a match, because you have been here since breakfast."},{"id":"B","text":"Tell me more about the match so that I can work out where you really went."},{"id":"C","text":"That sounds like a good morning. It is nearly lunchtime now, so shall we walk to the dining room together?"},{"id":"D","text":"Why do you keep making up stories about where you have been?"}]}'::jsonb, '{"answer":"C","feedback":{"A":"Incorrect. Correcting the account cannot repair the memory gap and increases anxiety and resistance.","B":"Incorrect. Asking for detail reinforces the confabulation and encourages it to grow.","C":"Correct. Accepting the statement without reinforcing it and redirecting to the present protects dignity and orientation.","D":"Incorrect. This accuses the client of deliberate deception, which confabulation is not."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Korsakoff syndrome', 'Responding to confabulation', 'Hard', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_SATA_551011', 'SATA', 'A client is starting disulfiram. Which products should the nurse teach the client to avoid? Select all that apply.', 'Disulfiram blocks the enzyme that clears acetaldehyde, so even a small amount of alcohol produces flushing, a throbbing headache, vomiting, tachycardia and hypotension within minutes. The teaching problem is that alcohol is hidden in everyday products — mouthwash, aftershave and cologne, hand sanitiser, liquid cough and cold preparations, and flavouring extracts such as vanilla — and skin or inhaled exposure can be enough. The sensitivity persists for up to 14 days after the last dose, so avoidance continues well beyond stopping the drug.', '{"options":[{"id":"A","text":"Alcohol-based mouthwash"},{"id":"B","text":"Aftershave and cologne"},{"id":"C","text":"Alcohol-based hand sanitiser"},{"id":"D","text":"Liquid cough and cold preparations"},{"id":"E","text":"Paracetamol tablets"},{"id":"F","text":"Full-fat dairy products"},{"id":"G","text":"Caffeinated coffee"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Mouthwash is frequently alcohol-based and is a common trigger.","B":"Correct. Alcohol in aftershave and cologne can be absorbed through the skin and inhaled.","C":"Correct. Hand sanitiser is largely alcohol and is used many times a day without thought.","D":"Correct. Many liquid over-the-counter medicines use alcohol as a solvent.","E":"Incorrect. Paracetamol tablets contain no alcohol and are not restricted by disulfiram.","F":"Incorrect. Dairy products have no interaction with disulfiram.","G":"Incorrect. Caffeine does not interact with disulfiram, although it may add to jitteriness."}}'::jsonb,
 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Mental Health', 'Multisystem',
 'Disulfiram', 'Hidden sources of alcohol', 'Very easy', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_551012', 'MCQ', 'One neonate on the unit is 6 hours old, born to a woman who uses heroin, and is limp with a respiratory rate of 26 breaths per minute and pinpoint pupils. A second neonate, born 36 hours ago to a woman who uses heroin, is jittery with a shrill cry. How should the nurse interpret these findings?', 'The timing rule separates the two states. Signs in the first hours of life reflect drug still circulating in the neonate, so the picture is intoxication and looks like the adult overdose — sedation, hypotonia and respiratory depression. Once the drug clears, usually after the first day, withdrawal begins and drives the neonate up into jitteriness, a high-pitched cry and hyperirritability.', '{"options":[{"id":"A","text":"The 6-hour-old is showing intoxication and the 36-hour-old is showing withdrawal"},{"id":"B","text":"Both neonates are in withdrawal, at different levels of severity"},{"id":"C","text":"The 6-hour-old is in withdrawal and the 36-hour-old is intoxicated"},{"id":"D","text":"Both presentations are normal newborn behaviour and need no further action"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Depressed signs in the first hours indicate drug still on board; excitable signs after the first day indicate withdrawal.","B":"Incorrect. Withdrawal drives a neonate up, so hypotonia with a low respiratory rate does not fit withdrawal.","C":"Incorrect. This reverses the timing rule.","D":"Incorrect. A respiratory rate of 26 breaths per minute is below the normal newborn range and needs immediate attention."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Mental Health', 'Multisystem',
 'Neonatal substance exposure', 'Intoxication versus withdrawal timing', 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SATA_551013', 'SATA', 'A neonate is being observed for neonatal abstinence syndrome. Which findings should the nurse expect? Select all that apply.', 'Neonatal abstinence syndrome is withdrawal in a very small nervous system, so everything is exaggerated and nothing settles. The classic cluster is a shrill high-pitched cry, an infant who cannot be consoled by usual measures, an exaggerated startle, tremors, and feeding difficulty from an uncoordinated suck. Deep unbroken sleep and a diminished Moro reflex point in the opposite direction and suggest sedation instead.', '{"options":[{"id":"A","text":"A shrill, high-pitched cry"},{"id":"B","text":"Difficulty being consoled"},{"id":"C","text":"An exaggerated startle response"},{"id":"D","text":"Poor feeding with an uncoordinated suck"},{"id":"E","text":"Prolonged periods of deep, unbroken sleep"},{"id":"F","text":"A weak or absent Moro reflex"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. The high-pitched shrill cry is one of the most recognisable signs.","B":"Correct. The neonate is difficult to console with holding, feeding or swaddling.","C":"Correct. Hyperirritability produces an exaggerated startle to minimal stimulation.","D":"Correct. A disorganised suck and swallow leads to poor intake and poor weight gain.","E":"Incorrect. Withdrawing neonates sleep poorly and wake frequently.","F":"Incorrect. The Moro reflex is exaggerated, not diminished, in withdrawal."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Multisystem',
 'Neonatal abstinence syndrome', 'Recognising the signs', 'Very easy', 'CURATOR_LABEL', 'Remember', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_551014', 'MCQ', 'A client who took an opioid overdose is given naloxone. Within 2 minutes the respiratory rate rises from 6 to 16 breaths per minute and the client rouses. Which action is the PRIORITY now?', 'Naloxone works quickly but wears off faster than most opioids, especially long-acting or modified-release preparations. When it clears, the opioid still in the body can depress respiration again, so a client who looks well at 5 minutes may be in trouble at 45 minutes. Continued observation with repeat doses or an infusion is what keeps the client alive.', '{"options":[{"id":"A","text":"Continue close respiratory monitoring, because naloxone wears off before the opioid does"},{"id":"B","text":"Prepare the client for discharge now that the airway is protected"},{"id":"C","text":"Give a warm drink and allow the client to sleep undisturbed"},{"id":"D","text":"Administer an opioid analgesic to relieve the withdrawal symptoms naloxone has caused"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Re-sedation is expected once naloxone clears, so monitoring and repeat dosing continue.","B":"Incorrect. Discharge at this point risks the client arresting once the naloxone effect ends.","C":"Incorrect. Undisturbed sleep removes the observation that would detect returning respiratory depression.","D":"Incorrect. Giving an opioid back would restore the respiratory depression that was just reversed."}}'::jsonb,
 'Physiological Integrity', 'Pharmacological and Parenteral Therapies', 'Mental Health', 'Multisystem',
 'Naloxone', 'Monitoring after reversal', 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SATA_551015', 'SATA', 'A client who injects heroin declines to stop using but agrees to keep meeting the community nurse. Which harm-reduction measures should the nurse include? Select all that apply.', 'Harm reduction accepts that a client may continue to use and works to keep that client alive and free of infection until change becomes possible. Sterile equipment prevents bloodborne infection, take-home naloxone converts a fatal overdose into a survivable one, and not using alone means someone is there to give it. Making services conditional on abstinence simply removes the client from care, and mixing opioids with other depressants raises overdose risk rather than lowering it.', '{"options":[{"id":"A","text":"Supply sterile needles and syringes and a sharps container"},{"id":"B","text":"Teach the client and a household member to use a take-home naloxone kit"},{"id":"C","text":"Advise the client not to use alone and to leave the door unlocked"},{"id":"D","text":"Explain that stopping is safest when it is medically supervised, and offer a referral whenever the client is ready"},{"id":"E","text":"Explain that the service can only continue once the client agrees to stop using"},{"id":"F","text":"Advise that taking heroin together with alcohol makes an overdose less likely"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Sterile equipment prevents transmission of bloodborne infection.","B":"Correct. Naloxone in the home reverses an overdose before the ambulance arrives.","C":"Correct. Someone present, and able to get in, is what makes rescue possible.","D":"Correct. Supervised withdrawal is safer, and keeping the offer open respects the client''s readiness.","E":"Incorrect. Making care conditional on abstinence drives the client away from the service.","F":"Incorrect. Combining depressants multiplies the risk of fatal respiratory depression."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Mental Health', 'Multisystem',
 'Harm reduction', 'Community opioid care', 'Easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_551016', 'MCQ', 'A client admitted after a road traffic collision while intoxicated tells the nurse, "I could stop drinking whenever I wanted to." In the past year the client has lost a job and a driving licence because of alcohol. Which response by the nurse is BEST?', 'Denial in substance use is confronted, because leaving it intact keeps the client from treatment. The confrontation works by holding the client''s words alongside the client''s behaviour and letting the gap show, spoken from the nurse''s own observation rather than as an accusation or a label. Labelling raises defences, and agreeing with the denial makes the nurse part of it.', '{"options":[{"id":"A","text":"You say you can stop whenever you want, and I have noticed that in the past year you have lost your job and your licence because of drinking."},{"id":"B","text":"You are an alcoholic, and you have to admit that before anyone can help you."},{"id":"C","text":"Most people who say that are not being honest with themselves."},{"id":"D","text":"It sounds as though you have things under control, so we can talk about it another time."}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. This names the gap between what the client says and what the client does, from the nurse''s own observation, without attacking the person.","B":"Incorrect. Applying a label is an attack on the person and reliably increases defensiveness.","C":"Incorrect. Talking about people in general lets the client sidestep, and it implies dishonesty.","D":"Incorrect. Accepting the statement at face value colludes with the denial and postpones treatment."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Denial in substance use', 'Confronting the discrepancy', 'Hard', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_551017', 'MCQ', 'Three days after a spouse died, a client continues to lay a place at the table for the spouse and speaks of the spouse in the present tense. Which action by the nurse is appropriate?', 'Denial in grief is a protective first stage that gives the person time to absorb a loss that cannot be absorbed all at once, and it resolves as grieving proceeds. It is therefore supported rather than confronted — the opposite of denial in substance use, where the denial itself sustains the harm. Presence, listening and time are the intervention; stripping the defence away early leaves the client with nothing to hold.', '{"options":[{"id":"A","text":"Sit with the client and allow the client to talk about the spouse"},{"id":"B","text":"Point out to the client that the spouse has died and will not be coming to the table"},{"id":"C","text":"Quietly remove the extra place setting before the client comes to the table"},{"id":"D","text":"Arrange an urgent psychiatric referral for delusional thinking"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Presence and unhurried listening support the client through a normal early stage of grief.","B":"Incorrect. Confrontation is used for denial in substance use, not for denial in grief.","C":"Incorrect. Removing the setting takes the defence away without replacing it and offers no support.","D":"Incorrect. Three days after a death this is grief, not delusion, and needs no urgent referral."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Denial in grief', 'Supporting the stage', 'Very easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MAT_551018', 'MATRIX', 'For each client situation, select whether the nurse should confront the denial or support the denial.', 'The context decides the response. Where denial protects a behaviour that is causing the harm, as in substance use, it is confronted by placing the client words next to the client behaviour. Where denial protects a person from a loss that has already happened and cannot be changed, as in grief and in a new terminal diagnosis, it is supported, because it is buying the client time to absorb the news.', '{"rows":[{"id":"r1","text":"A client with cirrhosis says that drinking is not a problem, after two admissions this year with bleeding oesophageal varices"},{"id":"r2","text":"On the day a child died in a collision, the parent says that there must have been a mistake with the identification"},{"id":"r3","text":"A client says the cocaine use is only recreational, after missing 6 weeks of work"},{"id":"r4","text":"A client told this morning of a terminal diagnosis says the scan must belong to someone else"},{"id":"r5","text":"A client says a drink-driving charge was bad luck, and has three previous charges"}],"columns":[{"id":"c1","text":"Confront the denial"},{"id":"c2","text":"Support the denial"}],"row_label":"Situation"}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c1","r4":"c2","r5":"c1"},"feedback":{}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Denial', 'Confront or support', 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MAT_551019', 'MATRIX', 'For each behaviour, select whether it is an example of dependency, co-dependency or manipulation.', 'These three look similar at the bedside but need different interventions. In dependency the client has other people make decisions that the client could make. In co-dependency the other person draws self-worth from being the one who decides and rescues, and so keeps the client dependent. In manipulation the client induces another person to act against that person''s own interest, judgement or safety. Naming which one is in front of the nurse is what makes the intervention correct.', '{"rows":[{"id":"r1","text":"A client asks the spouse to decide each day which clothes to wear and which meals to eat"},{"id":"r2","text":"A spouse telephones the employer to report the client sick after a night of drinking, and says that being needed is what gives life meaning"},{"id":"r3","text":"A client persuades a student nurse to bring alcohol onto the unit, saying that nobody will find out"},{"id":"r4","text":"A client will not choose a therapy group without first asking the nurse to choose instead"},{"id":"r5","text":"A client tells the night nurse that another nurse has already agreed to an extra pass, which is untrue"}],"columns":[{"id":"c1","text":"Dependency"},{"id":"c2","text":"Co-dependency"},{"id":"c3","text":"Manipulation"}],"row_label":"Behaviour"}'::jsonb, '{"cells":{"r1":"c1","r2":"c2","r3":"c3","r4":"c1","r5":"c3"},"feedback":{}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Dependency, co-dependency and manipulation', 'Distinguishing the three', 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_551020', 'MCQ', 'The spouse of a client with alcohol dependence tells the nurse, "I am the only one who can manage him. I telephone his employer, I pay his fines, and without me he would be lost." Which outcome is most appropriate for the spouse?', 'Co-dependency is not simply helping too much; the helper''s self-worth has become tied to being indispensable, and the rescuing removes the consequences that would otherwise prompt the client to change. The work is therefore with the spouse — building sources of self-worth that do not depend on the client being unwell, and developing the ability to set one limit and hold it. Increasing the rescuing, in any form, deepens the pattern.', '{"options":[{"id":"A","text":"The spouse identifies sources of self-worth outside the relationship and states one limit the spouse will keep"},{"id":"B","text":"The spouse learns to recognise a relapse earlier so that the consequences can be prevented sooner"},{"id":"C","text":"The spouse takes over all household finances to reduce the stress on the client"},{"id":"D","text":"The spouse attends every treatment session so that the client is never left unsupported"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Co-dependency is addressed by rebuilding the self-esteem of the helper and their ability to set and hold a limit.","B":"Incorrect. Preventing consequences more efficiently is the co-dependent behaviour itself, done better.","C":"Incorrect. Taking over more of the client''s responsibilities increases the dependency in both directions.","D":"Incorrect. Constant attendance keeps the spouse''s identity anchored in being indispensable."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Co-dependency', 'Goal setting with the family member', 'Hard', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MCQ_551021', 'MCQ', 'A client on an inpatient unit tells the night nurse that the day nurse always allows an extra hour of telephone use after lights out. The night nurse knows that this is not the case. Which action by the nurse is most appropriate?', 'Manipulation succeeds when staff respond differently to the same request, so the intervention is a single clear limit applied the same way by everyone. Restating the rule without argument, holding to it, and passing the attempt on at handover closes the gap the client is working in. Granting the request once, even with a promise to review it later, teaches that persistence works.', '{"options":[{"id":"A","text":"Restate the unit rule, hold to it, and report the request at handover so that all staff respond the same way"},{"id":"B","text":"Allow the extra hour tonight and review the rule with the client in the morning"},{"id":"C","text":"Ask the client to explain why the client feels a need to break unit rules"},{"id":"D","text":"Refer the request to the healthcare provider so that the rule can be reconsidered"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A limit that every team member enforces identically removes the inconsistency manipulation depends on.","B":"Incorrect. Granting the request once rewards the behaviour and guarantees it will be repeated.","C":"Incorrect. Inviting explanation at this moment turns a limit into a negotiation.","D":"Incorrect. Passing a routine unit rule to the provider avoids the nursing responsibility to set the limit."}}'::jsonb,
 'Safe and Effective Care Environment', 'Management of Care', 'Mental Health', 'Psychiatric/Mental Health',
 'Manipulation', 'Consistent limit setting', 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_DO_551022', 'DRAG_ORDER', 'Place the stages of grief described by Kubler-Ross in the order in which they are classically described, from first to last. One option will not be used.', 'The classic sequence is denial, anger, bargaining, depression and acceptance. Knowing the order matters less than knowing what the nurse does at each point — accept denial without confronting it, allow anger without taking it personally, listen to bargaining without correcting it, stay present in depression rather than trying to cheer the client, and support the plans a client makes in acceptance. Clients move back and forth and may not reach every stage.', '{"slots":[{"id":"s1","target_text":"1st"},{"id":"s2","target_text":"2nd"},{"id":"s3","target_text":"3rd"},{"id":"s4","target_text":"4th"},{"id":"s5","target_text":"5th"}],"tokens":[{"id":"t1","text":"Denial"},{"id":"t2","text":"Anger"},{"id":"t3","text":"Bargaining"},{"id":"t4","text":"Depression"},{"id":"t5","text":"Acceptance"},{"id":"t6","text":"Resolution of the crisis within 6 weeks"}]}'::jsonb, '{"slots":{"s1":"t1","s2":"t2","s3":"t3","s4":"t4","s5":"t5"}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Stages of grief', 'Classic sequence', 'Very easy', 'CURATOR_LABEL', 'Remember', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_551023', 'MCQ', 'Which client should the nurse refer for assessment of complicated grief?', 'Normal grief hurts but it moves — the person gradually resumes roles and relationships even while the sadness continues. Complicated grief is prolonged, frozen and disabling, and thoughts of joining the dead person make it urgent. Anticipatory grief, which begins before a death, is a normal process that can ease later adjustment rather than a sign of pathology.', '{"options":[{"id":"A","text":"A client who, 2 years after a spouse died, keeps the bedroom untouched, has not returned to work and reports daily thoughts of joining the spouse"},{"id":"B","text":"A client who weeps when speaking of a parent who died 4 months ago but has returned to work"},{"id":"C","text":"A client whose partner has advanced cancer and who has begun to grieve the coming loss"},{"id":"D","text":"A client who feels angry with a sibling who died 6 weeks ago"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Grief that is unchanged after 2 years, prevents functioning and includes thoughts of joining the deceased is complicated grief.","B":"Incorrect. Weeping while functioning at 4 months is expected in normal grief.","C":"Incorrect. This is anticipatory grief, a normal response that can support later adjustment.","D":"Incorrect. Anger is a recognised stage of normal grief and is expected at 6 weeks."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Complicated grief', 'Deciding on referral', 'Medium', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SELN_551024', 'SELECT_N', 'A client has died on the ward and the family has just arrived. Which 3 actions should the nurse take?', 'Bad news is given plainly, in words that cannot be misread — softened language such as "we lost him" leaves families uncertain what has happened. After the news, families need private, unhurried time with the body, permission to touch or hold, and a nurse who can stay quiet rather than fill the silence with reassurance. Predicting how they will feel, hurrying them, or discouraging viewing takes away choices that help grieving.', '{"options":[{"id":"A","text":"Offer the family private time with the body and say that they may touch or hold the person"},{"id":"B","text":"Tell the family plainly that the person has died, using the word died"},{"id":"C","text":"Remain available and allow silence rather than filling it with reassurance"},{"id":"D","text":"Reassure the family that they will feel better once the funeral is over"},{"id":"E","text":"Encourage the family to leave promptly so that the bed can be prepared"},{"id":"F","text":"Advise the family not to view the body so that they can remember the person as they were"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Correct. Private time and explicit permission to touch the person support the beginning of grieving.","B":"Correct. Plain, unambiguous words prevent the family misunderstanding what has happened.","C":"Correct. Silence with a nurse present is more useful than reassurance the family cannot yet take in.","D":"Incorrect. Predicting how the family will feel dismisses the grief they are feeling now.","E":"Incorrect. Hurrying a bereaved family for a bed is never a nursing priority.","F":"Incorrect. Viewing is the family''s choice and often helps them accept the death as real."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Care of the family after a death', 'Breaking the news', 'Very easy', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SATA_551025', 'SATA', 'A client comes to the community clinic 2 days after a house fire destroyed the family home and says that the usual ways of coping are not working. Which actions should the nurse take? Select all that apply.', 'A crisis exists when an event overwhelms the coping the person normally relies on; it is not a mental illness and it is self-limiting, usually resolving in about 4 to 6 weeks one way or the other. Crisis intervention is therefore short, practical and focused on the present problem, on restoring coping, and on mobilising the supports the client already has. Exploring origins and insight belongs to later therapy, and major irreversible decisions are avoided while judgement is strained.', '{"options":[{"id":"A","text":"Focus on the immediate problem and on coping over the next few days"},{"id":"B","text":"Identify the family, friends and community supports the client already has"},{"id":"C","text":"Explain that this intense state usually settles within about 4 to 6 weeks"},{"id":"D","text":"Take a more directive role than usual and help the client make a concrete short-term plan"},{"id":"E","text":"Begin exploring how childhood experiences have shaped the client''s reaction"},{"id":"F","text":"Encourage the client to make major life decisions now, while motivation is high"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Crisis work is anchored in the here and now, not in underlying personality.","B":"Correct. Existing supports are the fastest route back to equilibrium.","C":"Correct. A crisis is time-limited, and saying so restores some sense of control.","D":"Correct. A more directive stance is appropriate while the client''s capacity to problem-solve is reduced.","E":"Incorrect. Insight-oriented exploration is for later therapy, not for an acute crisis.","F":"Incorrect. Major decisions made during a crisis are often regretted, because judgement is impaired."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Crisis intervention', 'Principles of the approach', 'Easy', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MMR_551026', 'MATRIX_MR', 'For each nursing action, select every level of anxiety at which the action is appropriate. Each action may apply to more than one level.', 'Anxiety narrows the perceptual field as it rises. At mild anxiety perception is widened and learning is at its best; at moderate anxiety the field narrows so the nurse must direct attention and keep language simple; at severe anxiety and panic the field collapses, learning is impossible and the client cannot be left alone. The rule of thumb is that as the level rises the nurse does more and asks less — fewer words, simpler directions, a quieter environment and constant presence.', '{"rows":[{"id":"r1","text":"Use short, simple directions and repeat them calmly"},{"id":"r2","text":"Explore what triggered the feeling and problem-solve alternatives with the client"},{"id":"r3","text":"Stay with the client and move to a quiet area with minimal stimulation"},{"id":"r4","text":"Teach a new relaxation technique for the first time"},{"id":"r5","text":"Give the client written information to read later"}],"columns":[{"id":"c1","text":"Mild anxiety"},{"id":"c2","text":"Moderate anxiety"},{"id":"c3","text":"Severe anxiety or panic"}],"row_label":"Nursing action"}'::jsonb, '{"cells":{"r1":["c2","c3"],"r2":["c1","c2"],"r3":["c3"],"r4":["c1"],"r5":["c1"]},"feedback":{}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Levels of anxiety', 'Matching the approach to the level', 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_551027', 'MCQ', 'A newly admitted client washes both hands for 20 minutes before every meal and is therefore repeatedly late to the dining room. Which action by the nurse is most appropriate at this stage of the admission?', 'A compulsive ritual is the client''s current defence against overwhelming anxiety, not a habit to be broken by instruction. Preventing it abruptly removes the defence and the anxiety escalates, sometimes to panic. Early care allows time for the ritual within the daily schedule while a therapeutic relationship and alternative coping are built; limits on the time given are then introduced gradually and by agreement.', '{"options":[{"id":"A","text":"Build time for the handwashing into the schedule and tell the client when the meal will be served"},{"id":"B","text":"Remove the soap and hand towel from the room so that the ritual cannot be performed"},{"id":"C","text":"Tell the client that the hands are already clean and the washing is unnecessary"},{"id":"D","text":"Insist that the client comes to the dining room on time and stops the ritual"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Allowing time for the ritual while structuring the day controls anxiety and sets the ground for gradual limits.","B":"Incorrect. Blocking the ritual abruptly removes the defence and can precipitate panic.","C":"Incorrect. Logical argument does not reduce a compulsion, because the client already knows it is excessive.","D":"Incorrect. Demanding immediate cessation raises anxiety and damages the therapeutic relationship."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Obsessive-compulsive disorder', 'Managing a ritual', 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_CLZ_551028', 'CLOZE', 'A client has an intense fear of lifts and climbs nine flights of stairs every day to avoid using one. The treatment plan uses systematic desensitisation, in which exposure to the feared object is {1}, the client uses {2} during each step, and the nurse should {3}.', 'A phobia is a persistent, out-of-proportion fear that the client knows is excessive, which is why explaining that it is irrational changes nothing. Systematic desensitisation pairs a graded hierarchy of exposure with a relaxation response, because a body that is relaxed cannot simultaneously hold the fear response, and the client moves up the hierarchy only when each step is tolerated. Accepting that the fear is real to the client is what makes the client willing to attempt the first step.', '{"blanks":[{"id":"b1","choices":[{"id":"c1","text":"sudden and at full intensity"},{"id":"c2","text":"gradual and graded"}]},{"id":"b2","choices":[{"id":"c1","text":"a taught relaxation technique"},{"id":"c2","text":"a sedative given before every session"}]},{"id":"b3","choices":[{"id":"c1","text":"explain that the fear is irrational so that it can be dismissed"},{"id":"c2","text":"accept that the fear is real to the client"}]}]}'::jsonb, '{"answers":{"b1":"c2","b2":"c1","b3":"c2"},"feedback":{}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Phobia', 'Systematic desensitisation', 'Easy', 'CURATOR_LABEL', 'Understand', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_551029', 'MCQ', 'A client who survived a bus crash 6 months ago suddenly crouches in the day room, shielding the head and shouting that the bus is coming. Which action by the nurse is most appropriate?', 'In a flashback the client is re-experiencing the event as though it is happening now, so the task is to reconnect the client with present sensory reality. Grounding does this by using the name, the place, the date and concrete sensations the client can feel and see. Sudden touch may be experienced as part of the threat, and asking for a detailed account while the client is dissociated deepens the re-experiencing. Symptoms lasting beyond a month indicate post-traumatic stress disorder rather than an acute stress reaction.', '{"options":[{"id":"A","text":"Say the client''s name calmly, state where the client is and what the date is, and ask the client to feel the chair and name three things in the room"},{"id":"B","text":"Take the client by the arm and lead the client quickly to the bedroom"},{"id":"C","text":"Ask the client to describe the crash in full detail while the memory is vivid"},{"id":"D","text":"Tell the client that the crash was 6 months ago and there is nothing to be frightened of"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Grounding reorients the client to the present through name, place, time and concrete sensation.","B":"Incorrect. Unexpected touch and being moved may be experienced as part of the threat.","C":"Incorrect. Detailed recounting during a flashback intensifies the re-experiencing.","D":"Incorrect. Telling a frightened client there is nothing to fear dismisses an experience that feels entirely real."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Post-traumatic stress disorder', 'Grounding during a flashback', 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MMR_551030', 'MATRIX_MR', 'For each finding, select whether it is associated with anorexia nervosa, bulimia nervosa, or both. Select all that apply for each finding.', 'The two disorders share the driving psychology — an intense fear of weight gain and a distorted body image — and share the electrolyte damage caused by purging. They separate on weight and on the physical traces of the behaviour: anorexia nervosa produces significant underweight with amenorrhoea and lanugo, while bulimia nervosa usually occurs at or above expected weight and leaves the dental erosion and parotid swelling that repeated vomiting causes.', '{"rows":[{"id":"r1","text":"Body weight well below the expected range"},{"id":"r2","text":"Eroded dental enamel and swollen parotid glands"},{"id":"r3","text":"Serum potassium 2.9 mEq/L"},{"id":"r4","text":"Body weight within or above the expected range"},{"id":"r5","text":"Intense fear of gaining weight with a distorted body image"},{"id":"r6","text":"Amenorrhoea with fine downy hair over the trunk"}],"columns":[{"id":"c1","text":"Anorexia nervosa"},{"id":"c2","text":"Bulimia nervosa"}],"row_label":"Finding"}'::jsonb, '{"cells":{"r1":["c1"],"r2":["c2"],"r3":["c1","c2"],"r4":["c2"],"r5":["c1","c2"],"r6":["c1"]},"feedback":{}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Mental Health', 'Multisystem',
 'Eating disorders', 'Anorexia nervosa and bulimia nervosa', 'Hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');

INSERT INTO nclex_bank_items (
  item_id, question_type, stem, rationale, content, correct,
  client_needs_category, client_needs_subcategory, nursing_subject, body_system,
  topic, subtopic, difficulty, difficulty_source, bloom_level, tags,
  marks, is_published, is_builder_visible, is_free_sample, cat_pool, batch_id
) VALUES
('NCLEX_MCQ_551031', 'MCQ', 'A client with severe anorexia nervosa is admitted at 62% of expected body weight and nutritional replacement is begun. On the second day the nurse reviews the results below. Which result requires the most immediate action?', 'Reintroducing nutrition to a starved body triggers an insulin surge that drives phosphate, potassium and magnesium out of the bloodstream and into the cells. Phosphate falls fastest and matters most, because the heart and the respiratory muscles cannot generate energy without it, so a severely low phosphate precedes cardiac failure, arrhythmia and respiratory collapse. This is why refeeding starts low, advances slowly, and is accompanied by daily electrolytes and cardiac monitoring.', '{"options":[{"id":"A","text":"Serum phosphate 0.9 mg/dL"},{"id":"B","text":"Serum sodium 136 mEq/L"},{"id":"C","text":"Haemoglobin 11.2 g/dL"},{"id":"D","text":"Serum albumin 3.2 g/dL"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. Severe hypophosphataemia during refeeding precedes cardiac and respiratory failure and must be corrected immediately.","B":"Incorrect. A sodium of 136 mEq/L is within the normal range.","C":"Incorrect. Mild anaemia is common in malnutrition and does not need immediate action.","D":"Incorrect. A modestly low albumin is expected in malnutrition and changes slowly."}}'::jsonb,
 'Physiological Integrity', 'Reduction of Risk Potential', 'Mental Health', 'Multisystem',
 'Refeeding syndrome', 'Laboratory monitoring', 'Very hard', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SATA_551032', 'SATA', 'A client with anorexia nervosa is being cared for under a behavioural treatment contract. Which nursing actions support the plan? Select all that apply.', 'A behavioural contract works only if the terms, including the time allowed for a meal, are agreed in advance and then applied identically by every nurse, without argument or renegotiation at the table. Supervision during the meal and for a period afterwards prevents food being hidden or discarded and prevents purging, and a consistent weighing routine makes the weight record meaningful. Extending the meal on request, debating calories, or allowing the client to eat unobserved all shift control back to the disorder.', '{"options":[{"id":"A","text":"Remain with the client during the meal and for 1 hour afterwards"},{"id":"B","text":"Weigh the client at the same time each morning, after voiding and in a gown"},{"id":"C","text":"State the agreed consequences calmly and apply them consistently"},{"id":"D","text":"Extend the time allowed for the meal whenever the client asks for longer"},{"id":"E","text":"Allow the client to eat alone in the room when the dining room feels distressing"},{"id":"F","text":"Discuss the calorie content of each item whenever the client raises it"}]}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Correct. The hour after the meal is when food is discarded or vomited, so supervision continues.","B":"Correct. A fixed routine removes the variables the client might otherwise use to alter the recorded weight.","C":"Correct. Consistency without emotion is what makes a behavioural contract effective.","D":"Incorrect. The time limit is agreed in advance and held; extending it on request renegotiates the contract.","E":"Incorrect. Eating unobserved allows food to be hidden and undermines the contract.","F":"Incorrect. Debating calories draws the nurse into the preoccupation of the disorder and invites negotiation."}}'::jsonb,
 'Psychosocial Integrity', 'Psychosocial Integrity', 'Mental Health', 'Psychiatric/Mental Health',
 'Anorexia nervosa', 'Mealtime supervision and the contract', 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_MCQ_551033', 'MCQ', 'A 4-month-old infant is brought to the emergency department with a spiral fracture of the femur. The carer states that the infant rolled off the sofa. Which action should the nurse take FIRST?', 'A spiral fracture is produced by a twisting force, which a 4-month-old cannot generate, and an infant of that age cannot climb or crawl. An injury that does not match the developmental stage of the child or the account given is a recognised red flag for non-accidental injury. The nurse is a mandatory reporter and reports a reasonable suspicion; certainty and proof are the job of the investigating agency, not the nurse, and confronting the carer may place the child at greater risk.', '{"options":[{"id":"A","text":"Recognise that the injury does not fit the account and report the concern under the safeguarding policy"},{"id":"B","text":"Ask the carer to describe the fall again, in more detail, at the bedside"},{"id":"C","text":"Tell the carer that the explanation given is not believable"},{"id":"D","text":"Wait for the radiology report and the skeletal survey before raising any concern"}]}'::jsonb, '{"answer":"A","feedback":{"A":"Correct. A mismatch between the injury and the developmental stage requires a mandatory report of suspicion.","B":"Incorrect. Repeating the history does not change the mismatch and delays the report.","C":"Incorrect. Confronting the carer may escalate the situation and place the infant at greater risk.","D":"Incorrect. Reporting is based on reasonable suspicion; waiting for proof delays protection."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Mental Health', 'Multisystem',
 'Child abuse', 'Injury inconsistent with the account', 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SELN_551034', 'SELECT_N', 'A woman attends a clinic with bruises at several different stages of healing. Her partner answers every question on her behalf and does not leave her side. Which 3 actions should the nurse take?', 'Nothing can be assessed while the suspected abuser is present, so the first task is to create a private moment using an ordinary clinical reason that does not arouse suspicion. The question is then asked directly and without judgement, and the findings are documented factually with the client''s own words, because those notes may later be evidence. Telling a client to leave takes away her control and ignores the fact that leaving is the most dangerous period; the nurse offers a safety plan and resources, and the decision stays with the client.', '{"options":[{"id":"A","text":"Arrange to see the client alone, giving a routine-sounding clinical reason"},{"id":"B","text":"Ask directly and privately whether anyone at home is hurting her"},{"id":"C","text":"Document the injuries factually and record the client''s account in her own words"},{"id":"D","text":"Tell the client that she must leave the relationship today"},{"id":"E","text":"Ask the partner to explain how the bruises were caused"},{"id":"F","text":"Wait until the client raises the subject herself before asking anything"}],"select_count":3}'::jsonb, '{"answers":["A","B","C"],"feedback":{"A":"Correct. Assessment is impossible while the suspected abuser is present, and the reason given must not raise suspicion.","B":"Correct. A direct, non-judgemental question in private is the recommended approach.","C":"Correct. Factual documentation in the client''s own words may later serve as evidence.","D":"Incorrect. Directing the client to leave removes her control and ignores that leaving is the most dangerous time.","E":"Incorrect. Asking the partner gives the suspected abuser control of the account.","F":"Incorrect. Most clients will not raise abuse spontaneously, so the nurse asks."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Mental Health', 'Psychiatric/Mental Health',
 'Intimate partner abuse', 'Assessment and safety planning', 'Medium', 'CURATOR_LABEL', 'Apply', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728'),
('NCLEX_SATA_551035', 'SATA', 'A home care nurse visits an 82-year-old who lives with an adult child. Which findings should the nurse regard as indicators of possible elder abuse? Select all that apply.', 'Elder abuse includes neglect and financial exploitation as well as physical injury, and neglect is the most common form. Pressure areas and dehydration in a dependent adult left without food and fluid within reach, a pension taken over so that medicines go unbought, fearful deference before answering, and bruising in the pattern of a grip are all recognised indicators. Findings that simply reflect ageing or previous surgery are not indicators, and the nurse reports a suspicion rather than waiting for certainty.', '{"options":[{"id":"A","text":"Pressure ulcers and dehydration in a client who is left with no food or fluid within reach"},{"id":"B","text":"The adult child controls the client''s pension, and the client''s medicines have not been bought for a month"},{"id":"C","text":"The client looks to the adult child before answering any question and appears frightened"},{"id":"D","text":"Bruising over both upper arms in the pattern of a grip"},{"id":"E","text":"A well-healed abdominal surgical scar from an operation 10 years ago"},{"id":"F","text":"The client uses a walking frame indoors"}]}'::jsonb, '{"answers":["A","B","C","D"],"feedback":{"A":"Correct. Pressure damage with dehydration in a dependent adult indicates neglect.","B":"Correct. Controlling the income so that essentials go unmet is financial abuse.","C":"Correct. Fearful deference to the carer before speaking is a recognised behavioural indicator.","D":"Correct. Symmetrical grip-pattern bruising suggests the client was held forcibly.","E":"Incorrect. An old surgical scar is an expected finding and is unrelated to abuse.","F":"Incorrect. Using a walking frame reflects mobility needs, not abuse."}}'::jsonb,
 'Safe and Effective Care Environment', 'Safety and Infection Control', 'Mental Health', 'Multisystem',
 'Elder abuse', 'Indicators on a home visit', 'Easy', 'CURATOR_LABEL', 'Analyze', '{}', 1, TRUE, TRUE, FALSE, FALSE, 'gapfill-20260728');
